{"chunk_id":"ce3d65","wall_time_seconds":0.000009549,"exit_code":0,"original_token_count":1752,"output":"#!/usr/bin/env python3
"""One append-only event log per repo: <main checkout>/.orch/events.jsonl. 小弟 append with report.sh; bp reads it.

  report.sh <kind> "<白話一句>" [--card K12] [--stage S] [--pr N] [--result <URL|/abs/path>] [--needs 決定|看|無]
  orch_events.py path       print the events file this directory resolves to

kind = started | stage | blocked | question | pr-open | done   (the turn hook also writes idle-unreported / waiting)
Events file: --events > $ORCH_EVENTS > <main checkout of the current repo>/.orch/events.jsonl
Agent: --agent > $ORCH_AGENT (launch.sh exports it). No --card: bp puts the event on the agent's newest open card.
Line = {"ts", "agent", "card", "kind", "summary", optional "stage", "pr", "result", "needs", "src"}.
"""
import fcntl, json, os, re, subprocess, sys
from contextlib import contextmanager
from datetime import datetime

KINDS = ("started", "stage", "blocked", "question", "pr-open", "done", "idle-unreported", "waiting")
NEEDS = ("決定", "看", "無")


def now_iso():
    return datetime.now().astimezone().isoformat(timespec="seconds")


def git(cwd, *args):
    try:
        r = subprocess.run(["git", "-C", cwd, *args], capture_output=True, text=True, timeout=10)
    except (OSError, subprocess.TimeoutExpired):
        return ""
    return r.stdout if not r.returncode else ""


def main_checkout(cwd):
    """The main checkout of the repo that cwd is in (also from a linked worktree or a submodule); "" outside git."""
    out = git(cwd, "rev-parse", "--path-format=absolute", "--git-dir", "--git-common-dir", "--show-toplevel").splitlines()
    if len(out) < 3:
        return ""
    if out[0] == out[1]:
        return out[2]  # already in the main checkout (inside a submodule, worktree list would name .git/modules/…)
    first = git(cwd, "worktree", "list", "--porcelain").split("\n", 1)[0]
    return first[len("worktree "):] if first.startswith("worktree ") else ""


def exclude_orch_dir(top):
    """Keep <repo>/.orch/ out of git without touching the repo's .gitignore (info/exclude covers every worktree)."""
    common = git(top, "rev-parse", "--path-format=absolute", "--git-common-dir").strip()
    if not common:
        return
    path = os.path.join(common, "info", "exclude")
    try:
        with open(path) as f:
            if any(line.strip() in (".orch", ".orch/", "/.orch/") for line in f):
                return
    except OSError:
        pass
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "a") as f:
        f.write("\n.orch/\n")


def events_path(explicit=None, cwd=None):
    if explicit:
        return os.path.abspath(explicit)
    if os.environ.get("ORCH_EVENTS"):
        return os.environ["ORCH_EVENTS"]
    top = main_checkout(cwd or os.getcwd())
    if not top:
        sys.exit("orch_events: not inside a git repo and ORCH_EVENTS is not set; pass --events <abs path>")
    return os.path.join(top, ".orch", "events.jsonl")


@contextmanager
def locked(path):
    """Hold an exclusive lock on <path>.lock for the block."""
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path + ".lock", "w") as lk:
        fcntl.flock(lk, fcntl.LOCK_EX)
        yield


def write_json(path, data):
    """Atomic write: a reader never sees half a file."""
    with open(path + ".tmp", "w") as f:
        json.dump(data, f, ensure_ascii=False, indent=1)
    os.replace(path + ".tmp", path)


def opts(args):
    """--key value pairs into a dict; everything else is positional."""
    pos, kv, i = [], {}, 0
    while i < len(args):
        if args[i].startswith("--") and i + 1 < len(args):
            kv[args[i][2:]] = args[i + 1]
            i += 2
        else:
            pos.append(args[i])
            i += 1
    return pos, kv


def append(path, ev):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "a") as f:
        fcntl.flock(f, fcntl.LOCK_EX)
        f.write(json.dumps(ev, ensure_ascii=False) + "\n")
        fcntl.flock(f, fcntl.LOCK_UN)
    return ev


def make(kind, summary, agent="", card="", stage="", result="", pr=None, needs="", src="agent"):
    if kind not in KINDS:
        raise ValueError(f"kind must be one of {', '.join(KINDS)}")
    if kind == "pr-open" and pr is None:
        raise ValueError("pr-open needs --pr N")
    if needs and needs not in NEEDS:
        raise ValueError(f"needs must be one of {', '.join(NEEDS)}")
    card = card.strip().upper()
    if card and not re.fullmatch(r"K\d+", card):
        raise ValueError("card must look like K12")
    ev = {"ts": now_iso(), "agent": agent, "card": card, "kind": kind, "summary": summary.strip()}
    for k, v in (("stage", stage), ("result", result), ("pr", pr), ("needs", needs), ("src", src)):
        if v not in ("", None):
            ev[k] = v
    return ev


def read(path, offset=0):
    """Events after byte offset; returns (events, new_offset). A torn last line is left for the next read.
    A file that shrank (rotated by hand) is read again from the start."""
    try:
        if os.path.getsize(path) < offset:
            offset = 0
        with open(path, "rb") as f:
            f.seek(offset)
            data = f.read()
    except OSError:
        return [], offset
    out, used = [], 0
    for raw in data.split(b"\n")[:-1]:
        used += len(raw) + 1
        try:
            ev = json.loads(raw)
        except ValueError:
            continue
        if isinstance(ev, dict):
            out.append(ev)
    return out, offset + used


def cli(argv):
    if not argv or argv[0] in ("-h", "--help"):
        print(__doc__)
        return 0
    if argv[0] == "path":
        print(events_path())
        return 0
    pos, kv = opts(argv)
    if len(pos) < 2:
        sys.exit('usage: report.sh <kind> "<白話一句>" [--card K12] [--stage S] [--pr N] [--result URL] [--needs 決定|看|無]')
    if re.search(r"(^|[\s/（(「])\.orch/", pos[1]):
        sys.exit("summary 不要放 .orch/ 路徑（使用者不一定打得開）；結果檔用 --result <絕對路徑>")
    try:
        pr = int(kv["pr"].lstrip("#")) if kv.get("pr") else None
        ev = make(pos[0], pos[1], agent=kv.get("agent") or os.environ.get("ORCH_AGENT", ""),
                  card=kv.get("card", ""), stage=kv.get("stage", ""),
                  result=kv.get("result", ""), pr=pr, needs=kv.get("needs", ""), src=kv.get("src", "agent"))
    except ValueError as e:
        sys.exit(f"report: {e}")
    path = events_path(kv.get("events"))
    append(path, ev)
    print(f"event {ev['kind']} {ev['card'] or '-'} -> {path}")
    return 0


if __name__ == "__main__":
    sys.exit(cli(sys.argv[1:]))
